// Demo program for: Ticketmaster (concert ticket platform)
// Public record -- Ticketmaster, AXS, Dice — the complete database of concert ticket platforms.
// Run it with: node demo.js   (works as-is on any PC with Node.js)
const record = {
  id: "JAH-TIX-000001",
  title: "Ticketmaster",
  kind: "concert ticket platform",
  developer: "Live Nation",
  platforms: "any modern web browser, Android, iOS and iPadOS",
  license: "Commercial"
};
function demo() {
  console.log("=== " + record.title + " ===");
  console.log("Kind:      " + record.kind);
  console.log("Developer: " + record.developer);
  console.log("Runs on:   " + record.platforms);
  console.log("License:   " + record.license);
  console.log("Status:    working version ready -- install it for " +
    record.platforms.split(",")[0].trim() + " and start using it today.");
}
demo();

